{
  "interpretation": {
    "name": "NutrunnerTighteningLine2ShortToolAbsence",
    "scope": {"line": 2, "station": "st2", "tool": "NR7", "variant": "F30"},
    "goal": "Tighten the fasteners of variant F30 at station st2 on line 2 with the shared nutrunner NR7, keeping the tool away from the crib as briefly as possible so line 3 can use it next.",
    "constraints": [
      "NR7 must be reserved before any tool-using step, and the reservation token is used to renew the lease in every tool-using step",
      "NR7 must be at st2 before configure-tool and tighten-fasteners",
      "The tightening program comes only from get-program for variant F30",
      "The tightening must be evaluated and recorded for traceability",
      "transport-tool is delegated to agvexecutor",
      "NR7 must be returned to the crib and the reservation released so that line 3 can obtain the tool"
    ],
    "preference": "Minimize the time NR7 is away from the crib: fetch the program and reserve the tool before the tool leaves, and evaluate and record while the tool is already travelling back. Release the reservation immediately after the tool is back in the crib.",
    "priority": "high",
    "horizon": "Single execution for the current request; the tool is released for line 3 right after return to the crib.",
    "requested_capabilities": [],
    "omit_services": []
  },
  "recipe": {
    "name": "line2-nutrunner-tightening",
    "first_action": "Prepare",
    "actions": [
      {
        "name": "Prepare",
        "next": "DeliverTool",
        "steps": [
          {
            "name": "reserve-nr7",
            "service": "reserve-tool",
            "next": [],
            "dep": [],
